<?php
declare(strict_types=1);
namespace Hls\Controllers;
use Hls\Http\View; use Hls\Http\Input; use Hls\Http\HttpError; use Hls\Repositories\Repository; use Hls\Middleware\Access; use Hls\Services\Audit;
final class FinanceInvoiceController { public function __construct(private Repository $repo,private View $view,private Access $access,private Audit $audit){} private function scope():array{return [$this->access->user['id'],$this->access->user['all_branches']];}
 public function index():void{$this->access->demand('finance.invoice.view');$rows=$this->repo->all('SELECT i.*,c.name customer_name,b.name branch_name FROM fin_invoices i JOIN md_customers c ON c.id=i.customer_id JOIN branches b ON b.id=i.branch_id WHERE i.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY i.id DESC',$this->scope());$branches=$this->repo->all('SELECT id,code,name FROM branches WHERE active=1 ORDER BY code');$customers=$this->repo->all('SELECT id,code,name,branch_id FROM md_customers WHERE active=1 ORDER BY name');$this->view->render('finance-invoices',['title'=>'Invoice','rows'=>$rows,'branches'=>$branches,'customers'=>$customers,'error'=>null]);}
 public function save():void{$this->access->demand('finance.invoice.create');$branch=Input::id($_POST,'branch_id');$this->access->demandBranch($branch);$customer=Input::id($_POST,'customer_id');$date=Input::text($_POST,'invoice_date',10);$due=Input::text($_POST,'due_date',10,false);$ds=$_POST['description']??[];$qs=$_POST['quantity']??[];$ps=$_POST['unit_price']??[];if(!is_array($ds)||!is_array($qs)||!is_array($ps))throw new HttpError(422,'Item invoice tidak valid.');$lines=[];$total=0;foreach($ds as $i=>$d){$d=trim((string)$d);$q=(float)($qs[$i]??0);$p=(float)($ps[$i]??-1);if($d===''||$q<=0||$p<0)continue;$line=round($q*$p,2);$lines[]=[$d,$q,$p,$line];$total=round($total+$line,2);}if(!$lines)throw new HttpError(422,'Minimal satu item bernilai positif diperlukan.');if(!$this->repo->one('SELECT id FROM md_customers WHERE id=? AND branch_id=? AND active=1',[$customer,$branch]))throw new HttpError(422,'Customer tidak tersedia pada cabang tersebut.');$this->repo->db->beginTransaction();try{$ref='INV-DRAFT-'.bin2hex(random_bytes(8));$this->repo->run('INSERT INTO fin_invoices(branch_id,customer_id,internal_ref,status,invoice_date,due_date,subtotal,total_amount,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,NOW(),NOW())',[$branch,$customer,$ref,'DRAFT',$date,$due?:null,$total,$total,$this->access->user['id']]);$id=(int)$this->repo->db->lastInsertId();foreach($lines as $l)$this->repo->run('INSERT INTO fin_invoice_lines(invoice_id,description,quantity,unit_price,line_total,created_at) VALUES(?,?,?,?,?,NOW())',[$id,...$l]);$this->repo->db->commit();$this->audit->record((int)$this->access->user['id'],'finance_invoice_created','fin_invoices',$id,['lines'=>count($lines),'total'=>$total]);$_SESSION['flash']='Draft invoice disimpan.';$this->view->redirect('/finance/invoices');}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}}
 public function detail():void{$this->access->demand('finance.invoice.view');$id=Input::id($_GET,'id');$row=$this->repo->one('SELECT i.*,c.name customer_name,b.name branch_name FROM fin_invoices i JOIN md_customers c ON c.id=i.customer_id JOIN branches b ON b.id=i.branch_id WHERE i.id=? AND i.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1)',[$id,...$this->scope()]);if(!$row)throw new HttpError(404,'Invoice tidak ditemukan.');$lines=$this->repo->all('SELECT * FROM fin_invoice_lines WHERE invoice_id=? ORDER BY id',[$id]);$this->view->render('finance-invoice-detail',['title'=>'Detail Invoice','row'=>$row,'lines'=>$lines]);}
 public function edit():void{$this->access->demand('finance.invoice.edit');$id=Input::id($_GET,'id',true)?:Input::id($_POST,'id');$row=$this->repo->one('SELECT i.*,c.name customer_name FROM fin_invoices i JOIN md_customers c ON c.id=i.customer_id WHERE i.id=?',[$id]);if(!$row||$row['status']!=='DRAFT'||!$this->access->branch((int)$row['branch_id']))throw new HttpError(409,'Hanya draft dalam cakupan yang dapat diedit.');$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){ $version=Input::id($_POST,'version');$invoiceDate=trim((string)($_POST['invoice_date']??''));$dueDate=trim((string)($_POST['due_date']??''));$validDate=function(string $value,bool $required):?string{$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(($required&&$value==='')||($value!==''&&(!$d||$d->format('Y-m-d')!==$value)))throw new HttpError(422,'Tanggal invoice tidak valid.');return $value===''?null:$value;};$invoiceDate=$validDate($invoiceDate,true);$dueDate=$validDate($dueDate,false);if($dueDate!==null&&$dueDate<$invoiceDate)throw new HttpError(422,'Jatuh tempo tidak boleh sebelum tanggal invoice.');$ds=$_POST['description']??[];$qs=$_POST['quantity']??[];$ps=$_POST['unit_price']??[];$lines=[];$total=0;foreach($ds as $i=>$d){$d=trim((string)$d);$q=(float)($qs[$i]??0);$p=(float)($ps[$i]??-1);if($d===''&&$q==0&&$p==0)continue;if($d===''||$q<=0||$p<0)throw new HttpError(422,'Item invoice tidak valid.');$v=round($q*$p,2);$lines[]=[$d,$q,$p,$v];$total=round($total+$v,2);}if(!$lines)throw new HttpError(422,'Minimal satu item diperlukan.');$this->repo->db->beginTransaction();try{$locked=$this->repo->one('SELECT status,version FROM fin_invoices WHERE id=? FOR UPDATE',[$id]);if(!$locked||$locked['status']!=='DRAFT'||(int)$locked['version']!==$version)throw new HttpError(409,'Invoice berubah atau sudah tidak dapat diedit.');$this->repo->run('DELETE FROM fin_invoice_lines WHERE invoice_id=?',[$id]);foreach($lines as $l)$this->repo->run('INSERT INTO fin_invoice_lines(invoice_id,description,quantity,unit_price,line_total,created_at) VALUES(?,?,?,?,?,NOW())',[$id,...$l]);$this->repo->run('UPDATE fin_invoices SET invoice_date=?,due_date=?,subtotal=?,total_amount=?,version=version+1,updated_at=NOW() WHERE id=?',[$invoiceDate,$dueDate,$total,$total,$id]);$this->repo->db->commit();$this->audit->record((int)$this->access->user['id'],'finance_invoice_updated','fin_invoices',$id,['total'=>$total,'lines'=>count($lines),'invoice_date'=>$invoiceDate,'due_date'=>$dueDate]);$this->view->redirect('/finance/invoice-detail?id='.$id);}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();if($e instanceof HttpError)$error=$e->getMessage();else throw $e;}}$lines=$this->repo->all('SELECT * FROM fin_invoice_lines WHERE invoice_id=? ORDER BY id',[$id]);$this->view->render('finance-invoice-edit',['title'=>'Edit Invoice','row'=>$row,'lines'=>$lines,'error'=>$error]);}
 public function issue():void{$this->access->demand('finance.invoice.issue');$id=Input::id($_POST,'id');$this->repo->db->beginTransaction();try{$row=$this->repo->one('SELECT i.*,b.code branch_code FROM fin_invoices i JOIN branches b ON b.id=i.branch_id WHERE i.id=? FOR UPDATE',[$id]);if(!$row||!$this->access->branch((int)($row['branch_id']??0)))throw new HttpError(404,'Invoice tidak ditemukan.');if($row['status']!=='DRAFT'){$this->repo->db->rollBack();return;}$number='INV/'.$row['branch_code'].'/'.date('Y').'/'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$this->repo->run('UPDATE fin_invoices SET status="ISSUED",official_number=?,updated_at=NOW(),version=version+1 WHERE id=? AND status="DRAFT"',[$number,$id]);$this->repo->db->commit();$this->audit->record((int)$this->access->user['id'],'finance_invoice_issued','fin_invoices',$id,['number'=>$number]);$_SESSION['flash']='Invoice diterbitkan.';$this->view->redirect('/finance/invoice-detail?id='.$id);}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}}
}
